parameters.jsonBody:
={{ JSON.stringify({
  model: "claude-sonnet-4-6",
  max_tokens: 500,
  messages: [
    {
      role: "user",
      content: `You are a fraud risk analyst assistant at a bank. Given the following flagged transaction, write a concise risk summary (3-4 sentences) for a human fraud analyst. Explain WHY it was flagged, assign a risk level (LOW/MEDIUM/HIGH), and suggest one recommended next action (e.g. contact customer, block card, no action needed). Be specific and reference the actual numbers.

Transaction details:
- Transaction ID: ${$json.transaction_id}
- Customer ID: ${$json.customer_id}
- Timestamp: ${$json.transaction_ts}
- Amount: ${$json.amount}
- Merchant category: ${$json.merchant_category}
- Transaction location: ${$json.location}
- Customer's home city: ${$json.home_city}
- Flagged for high amount: ${$json.flag_high_amount}
- Flagged for unusual location: ${$json.flag_unusual_location}
- Flagged for rapid repeat transactions: ${$json.flag_rapid_repeat}
- Total rules triggered: ${$json.flag_count}`
    }
  ]
}) }}

